def _boot():
    srcs = _json.loads(_z.decompress(_b64.b85decode(_BLOB)).decode("utf-8"))

    ns_m = {}
    exec(compile(srcs["models.py"], "models.py", "exec"), ns_m)
    ns_c = {}
    exec(compile(srcs["content.py"], "content.py", "exec"), ns_c)
    ns_p = {}
    exec(compile(srcs["persistence.py"], "persistence.py", "exec"), ns_p)

    ns_e = {}
    for k in ("RNG", "AP_PER_DAY", "DAYS_PER_SEASON", "SEASONS",
              "abs_day", "new_state", "season_name"):
        ns_e[k] = ns_m[k]
    ns_e["C"] = _t.SimpleNamespace(**{k: v for k, v in ns_c.items() if not k.startswith("__")})
    ns_e["P"] = _t.SimpleNamespace(**{k: v for k, v in ns_p.items() if not k.startswith("__")})
    exec(compile(srcs["engine.py"], "engine.py", "exec"), ns_e)
    return ns_e["Game"]


_Game = _boot()
_game = None


def cmd(text: str) -> str:
    """唯一公开接口：输入一条（或分号分隔的多条）指令，返回文本 + 📊 状态栏。"""
    global _game
    if _game is None:
        _game = _Game()
    return _game.cmd(text)


__all__ = ["cmd"]
__version__ = "0.1.4"
